import { test, expect } from '@playwright/test';

test.describe('Async Image Upload with Progress Percentage', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should display upload progress percentage as image uploads', async ({ page }) => {
    // Intercept the upload API call
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Locate and upload file using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await fileInput.setInputFiles('tests/fixtures/sample-image.jpg');

    // Wait for upload to start
    const uploadButton = page.getByRole('button', { name: /start upload/i });
    await expect(uploadButton).toBeVisible();
    await uploadButton.click();

    // Wait for progress indicator to appear
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Verify progress percentage is displayed
    const progressText = page.getByText('Uploading...');
    await expect(progressText).toBeVisible();

    // Wait for upload to complete
    await page.waitForTimeout(500);

    // Verify success message appears
    const successMessage = page.getByText('Upload successful');
    await expect(successMessage).toBeVisible();

    // Verify progress bar reaches 100%
    await expect(progressBar).toHaveValue(100);

    // Verify image preview is displayed
    const imagePreview = page.getByRole('img', { name: /sample image/i });
    await expect(imagePreview).toBeVisible();
  });

  test('should handle failed upload and display error message', async ({ page }) => {
    // Intercept the upload API call and simulate failure
    await page.route('**/api/upload', (route) => {
      route.abort('Failed to upload image');
    });

    // Locate and upload file using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await fileInput.setInputFiles('tests/fixtures/sample-image.jpg');

    // Wait for upload button to appear
    const uploadButton = page.getByRole('button', { name: /start upload/i });
    await expect(uploadButton).toBeVisible();

    // Click upload button
    await uploadButton.click();

    // Wait for progress indicator to appear
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Verify progress percentage is displayed
    const progressText = page.getByText('Uploading...');
    await expect(progressText).toBeVisible();

    // Wait for upload to fail
    await page.waitForTimeout(500);

    // Verify error message appears
    const errorMessage = page.getByText('Upload failed');
    await expect(errorMessage).toBeVisible();

    // Verify progress bar does not reach 100%
    await expect(progressBar).not.toHaveValue(100);

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
  });
});
